import { Stack } from "@mui/material";
import React, { useEffect } from "react";
import { Navigate, Outlet } from "react-router-dom";
import { useDispatch, useSelector } from "react-redux";
import webSocketService from "../../webSocketService";
import useResponsive from "../../hooks/useResponsive";
import SideNav from "./SideNav";
import { FetchUserProfile, SelectConversation, showSnackbar } from "../../redux/slices/app";
import { UpdateDirectConversation, AddDirectConversation, AddDirectMessage, } from "../../redux/slices/conversation";
import AudioCallNotification from "../../sections/main/Audio/CallNotification";
import VideoCallNotification from "../../sections/main/Video/CallNotification";
import { PushToAudioCallQueue, UpdateAudioCallDialog, } from "../../redux/slices/audioCall";
import AudioCallDialog from "../../sections/main/Audio/CallDialog";
import VideoCallDialog from "../../sections/main/Video/CallDialog";
import { PushToVideoCallQueue, UpdateVideoCallDialog } from "../../redux/slices/videoCall";


const DashboardLayout = () => {


  const isDesktop = useResponsive("up", "md");
  const { user_id } = useSelector((state) => state.auth);
  const { open_audio_notification_dialog, open_audio_dialog } = useSelector((state) => state.audioCall);
  const { open_video_notification_dialog, open_video_dialog } = useSelector((state) => state.videoCall);
  const { conversations, current_conversation } = useSelector((state) => state.conversation.direct_chat);
  const { isLoggedIn, token } = useSelector((state) => state.auth);
  const dispatch = useDispatch();


  useEffect(() => {
    dispatch(FetchUserProfile());
  }, []);

  const handleCloseAudioDialog = () => {
    dispatch(UpdateAudioCallDialog({ state: false }));
  };
  const handleCloseVideoDialog = () => {
    dispatch(UpdateVideoCallDialog({ state: false }));
  };
  const userId = window.localStorage.getItem("user_id");
  const subscriptions = [];

  useEffect(() => {
    const subscriptionsMap = new Map(); // Track active subscriptions

    if (isLoggedIn) {
      window.onload = function () {
        if (!window.location.hash.includes('loaded')) {
          window.location.hash = 'loaded';
          window.location.reload();
        }
      };

      if (!webSocketService.connected) {
        webSocketService.connect({ token });
      }

      setTimeout(() => {
        const subscribeToEndpoint = (endpoint, callback) => {
          // Check if already subscribed
          if (!subscriptionsMap.has(endpoint)) {
            const subscription = webSocketService.subscribe(endpoint, callback);
            subscriptionsMap.set(endpoint, subscription); // Store subscription
            subscriptions.push(subscription); // Keep the existing array of subscriptions
          }
        };

        // Subscribe to endpoints only if not already subscribed
        subscribeToEndpoint(`/user/${userId}/topic/audio_call_notification`, (data) => {
          dispatch(PushToAudioCallQueue(data));
        });

        subscribeToEndpoint(`/user/${userId}/topic/video_call_notification`, (data) => {
          const parsedResponse = JSON.parse(data);
          dispatch(PushToVideoCallQueue(parsedResponse.data));
        });

        subscribeToEndpoint(`/user/${userId}/topic/new_message`, (data) => {
          const parsedResponse = JSON.parse(data);
          dispatch((dispatch, getState) => {
            const { conversation } = getState();
            const { current_conversation } = conversation.direct_chat;
            
            dispatch(AddDirectMessage({
              id: parsedResponse.conversation_id,
              type: "msg",
              subtype: parsedResponse.message.type,
              media: parsedResponse.message.media,
              mediaType: parsedResponse.message.mediaType,
              message: parsedResponse.message.text,
              incoming: parsedResponse.message.to === user_id,
              outgoing: parsedResponse.message.from === user_id,
              time: parsedResponse.message.createdAt,
            }));
          })
        });

        subscribeToEndpoint(`/user/${userId}/topic/start_conversation`, (response) => {
          const parsedResponse = JSON.parse(response);
          const existing_conversation = conversations?.find((el) => el.id === parsedResponse.data.id);
          if (existing_conversation) {
            dispatch(UpdateDirectConversation({ conversation: parsedResponse.data }));
          } else {
            dispatch(AddDirectConversation({ conversation: parsedResponse.data }));
          }
          dispatch(SelectConversation({ room_id: parsedResponse.data.id }));
        });

        subscribeToEndpoint(`/user/${userId}/topic/new_friend_request`, (data) => {
          dispatch(showSnackbar({ severity: "success", message: data }));
        });

        subscribeToEndpoint(`/user/${userId}/topic/request_accepted`, (data) => {
          // console.log(data);
          dispatch(showSnackbar({ severity: "success", message: data }));
        });

        subscribeToEndpoint(`/user/${userId}/topic/request_sent`, (data) => {
          const parsedResponse = JSON.parse(data);
          dispatch(showSnackbar({ severity: parsedResponse.status, message: parsedResponse.message }));
        });
      }, 1000);
    }

    return () => {
      subscriptions.forEach((el) => {
        if (webSocketService.connected) {
          el?.unsubscribe();
        }
      });
      webSocketService.disconnect();
      subscriptionsMap.clear(); // Clear the map on cleanup
    };
  }, []);

  if (!isLoggedIn) {
    return <Navigate to="/auth/login" />
  }

  return (
    <>
      <Stack direction="row">
        {isDesktop && (
          // SideBar
          <SideNav />
        )}

        <Outlet />
      </Stack>
      {open_audio_notification_dialog && (
        <AudioCallNotification open={open_audio_notification_dialog} handleClose={handleCloseAudioDialog} />
      )}
      {open_audio_dialog && (
        <AudioCallDialog
          open={open_audio_dialog}
          handleClose={handleCloseAudioDialog}
        />
      )}
      {open_video_notification_dialog && (
        <VideoCallNotification open={open_video_notification_dialog} handleClose={handleCloseVideoDialog} />
      )}
      {open_video_dialog && (
        <VideoCallDialog
          open={open_video_dialog}
          handleClose={handleCloseVideoDialog}
        />
      )}
    </>
  );
};

export default DashboardLayout;

